DROP TABLE IF EXISTS `sekai_galagame_lies_story_nodes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sekai_galagame_lies_story_nodes` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `node_key` varchar(50) NOT NULL,
  `label_name` varchar(100) NOT NULL,
  `chapter_no` int DEFAULT '0',
  `node_type` varchar(20) NOT NULL,
  `seq_no` int NOT NULL,
  `speaker_key` varchar(50) DEFAULT NULL,
  `speaker_name` varchar(50) DEFAULT NULL,
  `text` text,
  `bg_image` varchar(100) DEFAULT NULL,
  `sprites` text COMMENT 'JSON: [{"image":"","pos":""}]',
  `set_var` varchar(50) DEFAULT NULL,
  `set_value` varchar(255) DEFAULT NULL,
  `next_key` varchar(50) DEFAULT NULL,
  `ending_key` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `node_key` (`node_key`),
  KEY `idx_galagame_nodes_label` (`label_name`),
  KEY `idx_galagame_nodes_chapter` (`chapter_no`),
  KEY `idx_galagame_nodes_type` (`node_type`)
) ENGINE=InnoDB AUTO_INCREMENT=3757 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

