INSERT INTO `sekai_galagame_lies_story_nodes` VALUES (1,'s0','start',0,'set',0,'','','','','','ai_sprite_outfit','stage','s1',''),(2,'s1','start',0,'scene',1,'','','','bg station_sunbreak','','','','s2',''),(3,'s2','start',0,'narration',2,'','','穿过隧道，沿途的电线杆便被抛之身后。','','','','','s3',''),(4,'s3','start',0,'narration',3,'','','隆隆作响的火车在信号所前缓缓停下，灰暗的云朵将太阳遮的密不透风。','','','','','s4',''),(5,'s4','start',0,'narration',4,'','','车窗外，捏着报纸等待列车进站的乘客已经拿上行李站起身，几个身穿制服的车辆乘务员下车负责引导。','','','','','s5',''),(6,'s5','start',0,'narration',5,'','','白茫茫的天空，十一月的冷风钻不进车厢。','','','','','s6',''),(7,'s6','start',0,'narration',6,'','','第三节车厢，在靠近窗户的某个座位，顾天鹏望着窗外，叹了口气。','','','','','s7',''),(8,'s7','start',0,'narration',7,'','','重生到岛国的第十七年，刚从神川私塾毕业的顾天鹏，在十一月的第二周伊始，下定决心出门远足。','','','','','s8',''),(9,'s8','start',0,'narration',8,'','','和其他人的重生不同。','','','','','s9',''),(10,'s9','start',0,'narration',9,'','','没有觉醒系统之类的金手指，也没有好用的经验面板。','','','','','s10',''),(11,'s10','start',0,'narration',10,'','','唯一和别人不一样的地方，只是顾天鹏有个特殊的、难以派上用场的能力：','','','','','s11',''),(12,'s11','start',0,'narration',11,'','','只要在心里重复一遍对方说过的话，便能知道那句话是不是谎言。','','','','','s12',''),(13,'s12','start',0,'narration',12,'','','放在军事、政治领域，或许称得上了不得。','','','','','s13',''),(14,'s13','start',0,'narration',13,'','','但前提是别人会相信他能力确实存在，否则只会被当做开玩笑，或者中二过头了。','','','','','s14',''),(15,'s14','start',0,'narration',14,'','','六岁那一年，父亲在建筑工地意外丧生，母亲不久也病倒离世，顾天鹏没有其他可以依靠的任何亲戚。','','','','','s15',''),(16,'s15','start',0,'narration',15,'','','勉强靠社会资助完成了义务教育，不准备继续念大学。','','','','','s16',''),(17,'s16','start',0,'narration',16,'','','这次出门，顾天鹏手里只剩可以维持半年生计的一些现金，行李也只有用来更换的另一套衣服。','','','','','s17',''),(18,'s17','start',0,'narration',17,'','','他决定去越后汤泽放松一下。','','','','','s18',''),(19,'s18','start',0,'narration',18,'','','在春天来临的时候，也同样是在他正式找工作之前。','','','','','s19',''),(20,'s19','start',0,'narration',19,'','','合上德语杂志，顾天鹏靠在软软的靠背上，用手揉着眼皮放松。','','','','','s20',''),(21,'s20','start',0,'narration',20,'','','四下传来交谈声，仿佛将车厢闷进了玻璃瓶里，声音忽远忽近。','','','','','s21',''),(22,'s21','start',0,'narration',21,'','','行李箱的滚轮压过地板，发出清晰的吱咬声。','','','','','s22',''),(23,'s22','start',0,'narration',22,'','','火车停靠很长时间，乘客大都上了车。','','','','','s23',''),(24,'s23','start',0,'narration',23,'','','外面的乘务员正要收起方便残障人士进入的踏板，一个急匆匆的女声突然透过玻璃窗灌进来：','','','','','s24',''),(25,'s24','start',0,'dialogue',24,'ai','星野爱','等等，等等！我还没上车！','','','','','s25',''),(26,'s25','start',0,'set',25,'','','','','','ai_sprite_mode','false','s26',''),(27,'s26','start',0,'set',26,'','','','','','event_cg_mode','true','s27',''),(28,'s27','start',0,'scene',27,'','','','cg station_hurry_suitcase','','','','s28',''),(29,'s28','start',0,'narration',28,'','','被这声音惊扰的顾天鹏，不怎么感兴趣地抬起半只眼睛瞄去。','','','','','s29',''),(30,'s29','start',0,'narration',29,'','','只是一瞬间，能见的空气里，如同电影中一闪而过的某个画面。','','','','','s30',''),(31,'s30','start',0,'narration',30,'','','久违的阳光穿透云层，温柔的金色闪现在少女的眼里。','','','','','s31',''),(32,'s31','start',0,'narration',31,'','','秋日凄清荡然无存，凝眸望去，长空寥廓，白鸽掠过低空。','','','','','s32',''),(33,'s32','start',0,'narration',32,'','','无论经过一年，三年，还是二十年，一辈子。','','','','','s33',''),(34,'s33','start',0,'narration',33,'','','那副闯进灵魂的画面，顾天鹏永远记得真真切切。','','','','','s34',''),(35,'s34','start',0,'narration',34,'','','吹进站台的风扬起少女的深蓝色长发。','','','','','s35',''),(36,'s35','start',0,'narration',35,'','','她一手压低帽檐，一手拉着白色行李箱，碎花的连衣裙和羊绒围巾因风飘浮。','','','','','s36',''),(37,'s36','start',0,'dialogue',36,'conductor','短发女乘务员','下次要早点在这等着哦。','','','','','s37',''),(38,'s37','start',0,'narration',37,'','','短发女乘务员像是责怪孩子一样说她，顺手接过她的行李箱。','','','','','s38',''),(39,'s38','start',0,'scene',38,'','','','cg station_thanks_suitcase','','','','s39',''),(40,'s39','start',0,'dialogue',39,'ai','星野爱','嗯嗯，谢谢！','','','','','s40',''),(41,'s40','start',0,'narration',40,'','','少女漾出甜甜的笑，那笑容让人心情愉悦。','','','','','s41',''),(42,'s41','start',0,'set',41,'','','','','','ai_sprite_mode','false','s42',''),(43,'s42','start',0,'set',42,'','','','','','event_cg_mode','true','s43',''),(44,'s43','start',0,'scene',43,'','','','cg train_find_seat','','','','s44',''),(45,'s44','start',0,'narration',44,'','','不一会儿，火车缓缓启动，少女钻进车厢里，和顾天鹏在同一节。','','','','','s45',''),(46,'s45','start',0,'narration',45,'','','她对着座位上的序号挨个查看过去，像是检查座位损坏程度似的，最后停在顾天鹏身边。','','','','','s46',''),(47,'s46','start',0,'dialogue',46,'ai','星野爱','找到了。','','','','','s47',''),(48,'s47','start',0,'narration',47,'','','她眯细的眼睛终于舒展开，脸上挂着惊喜的表情。','','','','','s48',''),(49,'s48','start',0,'narration',48,'','','听见声音，顾天鹏支着手臂看过去。','','','','','s49',''),(50,'s49','start',0,'narration',49,'','','那是一双仿佛藏着星星的双眼。','','','','','s50',''),(51,'s50','start',0,'narration',50,'','','光是对视一眼，就让人仿若置身大山里的深空之下，想到皎洁的月光，又想到闪亮的舞台。','','','','','s51',''),(52,'s51','start',0,'narration',51,'','','即使没有阳光的点缀，那眼睛也美得让人失神，像是要把顾天鹏的气息全部夺走。','','','','','s52',''),(53,'s52','start',0,'narration',52,'','','少女没有立刻坐下，反而望了一眼头顶的行李架，又刻意拖动行李箱的滚轮。','','','','','s53',''),(54,'s53','start',0,'dialogue',53,'taku','顾天鹏','要帮忙吗？','','','','','s54',''),(55,'s54','start',0,'narration',54,'','','他犹豫了下问。','','','','','s55',''),(56,'s56','start',0,'narration',56,'','','顾天鹏没有等她第二次暗示，起身把白色行李箱接到手里。','','','','','s57',''),(57,'s57','start',0,'dialogue',57,'ai','星野爱','谢谢！那就拜托你了。','','','','','s58',''),(58,'s58','start',0,'narration',58,'','','她退后半步，把过道让出来。于是这场原本独自开始的旅行，在第一件行李被举起来时就改变了形状。','','','','','s76',''),(59,'s59','start',0,'narration',59,'','','顾天鹏没有立刻表现得过分热心，只是把手停在半空，等她真的需要帮助时再伸过去。','','','','','s60',''),(60,'s60','start',0,'narration',60,'','','他习惯给陌生人留出一点距离，即使对方有一双让人很难移开视线的眼睛。','','','','','s61',''),(61,'s61','start',0,'dialogue',61,'ai','星野爱','那个，可以帮我一下吗？','','','','','s62',''),(62,'s62','start',0,'dialogue',62,'taku','顾天鹏','当然。','','','','','s63',''),(63,'s63','start',0,'narration',63,'','','等她把请求说出口，他才接过行李箱。这个短短的停顿，让两个人都确认了彼此愿意靠近的速度。','','','','','s64',''),(64,'s64','start',0,'narration',64,'','','行李箱被稳稳推进行李架时，星野爱像验收工程一样抬头看了看，又把一只小兔子发卡从刘海边拨正。','','','','','s65',''),(65,'s65','start',0,'dialogue',65,'ai','星野爱','顾天鹏，你是不是那种一定要等别人开口，才会觉得不冒犯的人？','','','','','s66',''),(66,'s66','start',0,'dialogue',66,'taku','顾天鹏','差不多。','','','','','s67',''),(67,'s67','start',0,'dialogue',67,'ai','星野爱','那我要是不说，你就会一直看着？','','','','','s68',''),(68,'s68','start',0,'dialogue',68,'taku','顾天鹏','我会判断。','','','','','s69',''),(69,'s69','start',0,'dialogue',69,'ai','星野爱','判断失败的话呢？','','','','','s70',''),(70,'s70','start',0,'dialogue',70,'taku','顾天鹏','道歉。','','','','','s71',''),(71,'s71','start',0,'narration',71,'','','她听见这个答案，忍不住笑起来，却没有继续追问他的名字、年龄和秘密。','','','','','s72',''),(72,'s72','start',0,'narration',72,'','','两个人把话题停在车票、天气和下一站的时刻表上。那是一条更礼貌的路线，像在湿玻璃上画出的直线，清楚，却不够贪心。','','','','','s73',''),(73,'s73','start',0,'narration',73,'','','后来乘务员推着小车经过，星野爱买了一瓶热茶，没有买便当。顾天鹏也没有把巧克力拿出来。','','','','','s74',''),(74,'s74','start',0,'narration',74,'','','他们在同一张小桌前各自保留着一点空白，直到列车穿过县界，窗外的雨色慢慢压下来。','','','','','s75',''),(75,'s75','start',0,'jump',75,'','','','','','','','s217',''),(76,'s55','start',0,'menu',55,'','','','','','','','s76',''),(77,'s76','start',0,'narration',76,'','','等行李箱终于安置到头顶，少女整理好裙子，在他正对面的位置坐下。','','','','','s77',''),(78,'s77','start',0,'scene',77,'','','','bg train_table','','','','s78',''),(79,'s78','start',0,'set',78,'','','','','','ai_sprite_mode','true','s79',''),(80,'s79','start',0,'set',79,'','','','','','event_cg_mode','false','s80',''),(81,'s80','start',0,'sprite',80,'','','','','[{\"image\": \"heroine stage_neutral\", \"pos\": \"heroine_bust_center\"}]','','','s81',''),(82,'s81','start',0,'narration',81,'','','行李摆上架子，顾天鹏拍了拍手，重新坐好。','','','','','s82',''),(83,'s82','start',0,'dialogue',82,'ai','星野爱','谢谢，你叫什么呢？','','','','','s83',''),(84,'s83','start',0,'narration',83,'','','少女的脸上很适合挂着笑容。','','','','','s84',''),(85,'s84','start',0,'dialogue',84,'taku','顾天鹏','顾天鹏。','','','','','s85',''),(86,'s85','start',0,'dialogue',85,'ai','星野爱','星野爱。','','','','','s86',''),(87,'s86','start',0,'narration',86,'','','她把帽子摘下来，撩了下搭在脖颈和羊绒围巾交界处的长发。','','','','','s87',''),(88,'s87','start',0,'narration',87,'','','一股淡淡的清香弥散到空气中，如同刚摘下的樱桃一般。','','','','','s88',''),(89,'s88','start',0,'narration',88,'','','顾天鹏看愣神似的望着她。','','','','','s89',''),(90,'s89','start',